local function draw(frame)
  local image, palette = frame.image, frame.palette
  local sw, sh = monitor.getSize()
  local sourceW, sourceH = #image[1][1], #image
  local scale = math.min(sw / sourceW, sh / sourceH)
  local w = math.max(1, math.floor(sourceW * scale))
  local h = math.max(1, math.floor(sourceH * scale))
  local ox, oy = math.floor((sw-w)/2)+1, math.floor((sh-h)/2)+1
  for i=0,15 do
    if palette[i] then monitor.setPaletteColor(2^i, table.unpack(palette[i])) end
  end
  monitor.setBackgroundColor(colors.black)
  monitor.clear()
  for y=1,h do
    local iy = math.min(sourceH, math.floor((y-.5)*sourceH/h)+1)
    local row = image[iy]
    local chars, fg, bg = {}, {}, {}
    for x=1,w do
      local ix=math.min(sourceW,math.floor((x-.5)*sourceW/w)+1)
      chars[x]=row[1]:sub(ix,ix)
      fg[x]=row[2]:sub(ix,ix)
      bg[x]=row[3]:sub(ix,ix)
    end
    monitor.setCursorPos(ox,oy+y-1)
    monitor.blit(table.concat(chars),table.concat(fg),table.concat(bg))
  end
end
while true do
  for _,frame in ipairs(frames) do
    draw(frame)
    sleep(0.1)
  end
end
